/* ==========================================================================
   Axiom Public Lab — Reference Site
   Design system implementation
   ========================================================================== */

/* Imports */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=IBM+Plex+Mono:wght@400;500;600;700&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap');

/* Tokens */
:root {
  --slate: #1C2333;
  --chalk: #F0F2F5;
  --blueprint: #2563EB;
  --teal: #0D9488;
  --amber: #D97706;
  --line: #334155;
  --white: #FFFFFF;
  --plinth: #94A3B8;

  --font-heading: 'DM Sans', system-ui, sans-serif;
  --font-body: 'IBM Plex Sans', system-ui, sans-serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;

  --container-max: 1280px;
  --gutter: 24px;
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--slate);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img, svg { display: block; max-width: 100%; }
button { font: inherit; cursor: pointer; }
a { color: inherit; }
h1, h2, h3, h4 { margin: 0; font-family: var(--font-heading); font-weight: 700; letter-spacing: -0.02em; line-height: 1.15; }
p { margin: 0; }
ul, ol { margin: 0; padding: 0; list-style: none; }

/* Container */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 32px;
}

/* Mono utility */
.mono {
  font-family: var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 11px;
  font-weight: 500;
}

/* ==========================================================================
   Header / Navigation
   ========================================================================== */
.site-header {
  background: var(--slate);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 50;
}
.site-header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 32px;
  max-width: var(--container-max);
  margin: 0 auto;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--white);
}
.brand__mark {
  width: 32px;
  height: 32px;
  display: block;
}
.brand__name {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 17px;
  letter-spacing: -0.01em;
}
.brand__tag {
  display: block;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--plinth);
  margin-top: 2px;
}

.site-nav {
  display: flex;
  gap: 28px;
  align-items: center;
}
.site-nav a {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--plinth);
  text-decoration: none;
  transition: color 0.15s ease;
  padding: 6px 0;
  position: relative;
}
.site-nav a:hover { color: var(--white); }
.site-nav a.active {
  color: var(--white);
}
.site-nav a.active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -8px;
  height: 2px;
  background: var(--blueprint);
}
.nav-toggle { display: none; }

@media (max-width: 768px) {
  .site-header__inner { padding: 14px 20px; }
  .site-nav { display: none; flex-direction: column; gap: 16px; align-items: flex-start; }
  .site-nav.open {
    display: flex;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--slate);
    padding: 20px;
    border-bottom: 1px solid var(--line);
  }
  .nav-toggle {
    display: inline-flex;
    background: transparent;
    border: 1px solid var(--line);
    color: var(--white);
