}
@media (max-width: 600px) {
  .site-footer__grid { grid-template-columns: 1fr; gap: 32px; }
}

/* ==========================================================================
   Buttons
   ========================================================================== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 28px;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.02em;
  text-decoration: none;
  border: none;
  border-radius: 0;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
  white-space: nowrap;
}
.btn-primary {
  background: var(--blueprint);
  color: var(--white);
}
.btn-primary:hover { background: #1d54d9; }
.btn-outline-light {
  background: transparent;
  color: var(--white);
  border: 1px solid var(--white);
}
.btn-outline-light:hover { background: var(--white); color: var(--slate); }
.btn-outline-blue {
  background: transparent;
  color: var(--blueprint);
  border: 1px solid var(--blueprint);
  padding: 10px 20px;
  font-size: 13px;
}
.btn-outline-blue:hover { background: var(--blueprint); color: var(--white); }
.btn-teal {
  background: var(--teal);
  color: var(--white);
  padding: 14px 32px;
}
.btn-teal:hover { background: #0a7468; }
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 15px;
  color: var(--white);
  text-decoration: none;
}
.text-link .arrow {
  color: var(--amber);
  font-size: 16px;
  transition: transform 0.15s ease;
}
.text-link:hover { color: var(--blueprint); }
.text-link:hover .arrow { transform: translateX(4px); }

/* ==========================================================================
   Eyebrow with rule
   ========================================================================== */
.eyebrow {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--amber);
  display: inline-flex;
  align-items: center;
  gap: 12px;
}
.eyebrow::before {
  content: "";
  display: inline-block;
  width: 24px;
  height: 1.5px;
  background: var(--amber);
}
.eyebrow.no-rule::before { display: none; }
.eyebrow.teal { color: var(--teal); }
.eyebrow.teal::before { background: var(--teal); }
.eyebrow.plinth { color: var(--plinth); }
.eyebrow.plinth::before { background: var(--plinth); }

/* ==========================================================================
   Section base
   ========================================================================== */
section {
  position: relative;
}

/* ==========================================================================
   HERO (home-section-1)
   ========================================================================== */
.hero {
  background: var(--slate);
  color: var(--white);
  padding: 120px 0 96px;
  min-height: 92vh;
  display: flex;
  align-items: center;
  position: relative;
}
.hero__inner {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 32px;
}
.hero__eyebrow {
  margin-bottom: 40px;
}
.hero__headline {
  font-family: var(--font-heading);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.05;
  font-size: clamp(42px, 8.5vw, 112px);
  color: var(--white);
  margin: 0;
  max-width: 14ch;
}
.hero__headline .accent {
  color: var(--blueprint);
