}

/* ==========================================================================
   STATS strip (home-section-2)
   ========================================================================== */
.stats-strip {
  background: var(--blueprint);
  color: var(--white);
  padding: 56px 0 64px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
}
