}
@media (max-width: 900px) {
  .stats-strip__grid { grid-template-columns: 1fr 1fr; gap: 32px 0; }
  .stat-cell { padding: 0 16px; }
  .stat-cell:nth-child(odd) { border-left: 0; padding-left: 0; }
  .stat-cell:nth-child(3) { border-top: 1px solid rgba(255,255,255,0.2); padding-top: 32px; }
  .stat-cell:nth-child(4) { border-top: 1px solid rgba(255,255,255,0.2); padding-top: 32px; }
}
@media (max-width: 540px) {
