.services-grid__secondary {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  color: var(--blueprint);
  text-decoration: none;
}
.services-grid__secondary:hover { text-decoration: underline; }
@media (max-width: 1024px) { .services-grid__cards { grid-template-columns: 1fr 1fr; } }
@media (max-width: 640px) { .services-grid__cards { grid-template-columns: 1fr; }
  .service-card__watermark { display: none; }
}

/* ==========================================================================
   FAQ (services-section-3)
   ========================================================================== */
.faq {
  background: var(--slate);
  color: var(--white);
  padding: 96px 0;
}
.faq__inner {
  display: grid;
  grid-template-columns: 38% 58%;
  gap: 4%;
  align-items: start;
}
.faq__sticky {
  position: sticky;
  top: 100px;
}
.faq__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(24px, 2.8vw, 32px);
  color: var(--white);
  margin-top: 16px;
}
.faq__accent {
  width: 40px;
  height: 2px;
  background: var(--blueprint);
  margin-top: 20px;
}
.faq__count {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--plinth);
  margin-top: 24px;
}
.faq__list {
  border-top: 1px solid var(--line);
}
.faq-item {
  border-bottom: 1px solid var(--line);
}
.faq-item__btn {
  width: 100%;
  background: transparent;
  border: none;
  color: var(--white);
  text-align: left;
  padding: 22px 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 17px;
  letter-spacing: -0.01em;
  cursor: pointer;
}
.faq-item__toggle {
  font-family: var(--font-mono);
  font-size: 16px;
  color: var(--blueprint);
  flex-shrink: 0;
  width: 16px;
  text-align: center;
}
.faq-item__answer {
  display: none;
  padding: 0 0 22px;
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--plinth);
  max-width: 64ch;
}
.faq-item.open .faq-item__answer { display: block; }
@media (max-width: 900px) {
  .faq__inner { grid-template-columns: 1fr; gap: 32px; }
  .faq__sticky { position: static; }
}

/* ==========================================================================
   Team grid (team-section-2)
   ========================================================================== */
.team-grid {
  background: var(--chalk);
  padding: 72px 0;
}
.team-grid__head { margin-bottom: 32px; max-width: 720px; }
.team-grid__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(28px, 3.5vw, 40px);
  color: var(--line);
  letter-spacing: -0.02em;
  margin-top: 16px;
}
.team-grid__cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.team-card {
  background: var(--white);
  border-top: 3px solid var(--blueprint);
  padding: 24px;
  display: flex;
  flex-direction: column;
}
.team-card__tag {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--white);
  background: var(--teal);
  padding: 4px 8px;
  margin-bottom: 12px;
  align-self: flex-start;
}
.team-card__name {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 17px;
  color: var(--line);
  margin: 0;
}
.team-card__role {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--plinth);
  margin: 2px 0 10px;
}
.team-card__bio {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.55;
  color: var(--line);
}
.team-card__bottom-rule {
  height: 1px;
  background: rgba(51, 65, 85, 0.20);
  margin-top: auto;
  padding-top: 0;
  margin-bottom: -8px;
  margin-top: 16px;
}
@media (max-width: 1000px) { .team-grid__cards { grid-template-columns: 1fr 1fr; } }
@media (max-width: 640px) { .team-grid__cards { grid-template-columns: 1fr; } }

/* ==========================================================================
   Story block (team-section-3)
   ========================================================================== */
.story {
  background: var(--slate);
  color: var(--white);
  padding: 80px 0;
}
.story__inner {
  display: grid;
  grid-template-columns: 7fr 4fr;
  gap: 0;
  align-items: stretch;
}
.story__left {
  padding-right: 56px;
  border-right: 1px solid rgba(51, 65, 85, 0.6);
}
.story__title {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(30px, 3.6vw, 44px);
  letter-spacing: -0.02em;
  color: var(--white);
  margin-top: 16px;
}
.story__sub {
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.6;
  color: var(--plinth);
  margin-top: 16px;
}
.story__rule {
  height: 1px;
  background: rgba(51, 65, 85, 0.6);
  margin: 24px 0;
}
.story__body {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.88);
  max-width: 65ch;
  margin-bottom: 32px;
}
.story__right {
  padding-left: 56px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
}
.story__year {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(80px, 12vw, 140px);
  line-height: 1;
  color: var(--amber);
  letter-spacing: -0.04em;
  text-align: right;
}
.story__year-label {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--plinth);
  margin-top: 12px;
}
@media (max-width: 900px) {
  .story__inner { grid-template-columns: 1fr; gap: 32px; }
  .story__left { padding-right: 0; border-right: 0; order: 2; }
  .story__right { padding-left: 0; align-items: flex-start; order: 1; }
  .story__year-label { text-align: left; }
}

/* ==========================================================================
   Contact block (inquiries-section-2)
   ========================================================================== */
.contact {
  background: var(--chalk);
  padding: 100px 0;
}
.contact__inner {
  display: grid;
  grid-template-columns: 4fr 8fr;
  gap: 0;
  align-items: stretch;
}
.contact__sidebar {
  padding-right: 40px;
  border-right: 1px solid var(--line);
}
.contact__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 28px;
  letter-spacing: -0.02em;
  color: var(--line);
  margin-top: 16px;
}
.contact__sub {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--line);
  margin-top: 20px;
}
.contact__body {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.65;
  color: var(--plinth);
  margin-top: 24px;
}
.contact__badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--teal);
  border: 1px solid var(--line);
  padding: 8px 12px;
  margin-top: 32px;
}
.contact__form {
  background: var(--white);
  border: 2px solid var(--line);
  padding: 40px;
  margin-left: 40px;
}
.form-field {
  padding: 16px 0 24px;
  border-bottom: 1px solid var(--line);
}
.form-field:first-child { padding-top: 0; }
.form-field:last-of-type { border-bottom: 0; padding-bottom: 0; }
.form-field__label {
  display: block;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--line);
  margin-bottom: 4px;
}
.form-field__desc {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--plinth);
  margin-bottom: 8px;
}
.form-field__input,
.form-field__textarea {
  width: 100%;
  border: 1px solid var(--line);
  background: var(--chalk);
  padding: 12px;
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--line);
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s ease, border-width 0.15s ease;
}
.form-field__input:focus,
.form-field__textarea:focus {
  border: 2px solid var(--blueprint);
  padding: 11px;
}
.form-field__textarea { resize: vertical; min-height: 120px; font-family: var(--font-body); }
.contact__submit {
  margin-top: 32px;
}
@media (max-width: 900px) {
  .contact__inner { grid-template-columns: 1fr; gap: 32px; }
  .contact__sidebar { padding-right: 0; border-right: 0; padding-bottom: 32px; border-bottom: 1px solid var(--line); }
  .contact__form { margin-left: 0; padding: 28px; }
}

/* ==========================================================================
   Process steps (inquiries-section-3)
   ========================================================================== */
.process {
  background: var(--slate);
  color: var(--white);
  padding: 80px 0 72px;
}
.process__head { margin-bottom: 0; }
.process__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(26px, 3vw, 36px);
  letter-spacing: -0.02em;
  color: var(--white);
  margin-top: 12px;
  max-width: 24ch;
}
.process__rule-top {
  height: 1px;
  background: var(--line);
  margin: 48px 0 0;
}
.process__rule-bottom {
  height: 1px;
  background: var(--line);
  margin: 0 0 32px;
}
.process__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}
.process-step {
  padding: 32px 32px 32px 0;
  border-left: 1px solid var(--line);
  padding-left: 32px;
}
.process-step:first-child { border-left: 0; padding-left: 0; }
.process-step__number {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 48px;
  line-height: 1;
  color: var(--blueprint);
}
.process-step__title {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 18px;
  color: var(--white);
  margin-top: 16px;
  line-height: 1.2;
}
.process-step__desc {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.6;
  color: var(--plinth);
  margin-top: 12px;
}
.process__cta {
  margin-top: 32px;
}
@media (max-width: 900px) {
  .process__grid { grid-template-columns: 1fr; }
  .process-step { border-left: 0; border-top: 1px solid var(--line); padding-left: 0; padding-top: 24px; padding-bottom: 24px; }
  .process-step:first-child { border-top: 0; padding-top: 0; }
}

/* ==========================================================================
   Helpers
   ========================================================================== */
.flush-rule {
  height: 1px;
  background: var(--line);
  width: 100%;
}
.section-tag {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

