/* ==========================================================================
   Axiom Public Lab — Reference Site
   Design system implementation
   ========================================================================== */

/* Imports */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=IBM+Plex+Mono:wght@400;500;600;700&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap');

/* Tokens */
:root {
  --slate: #1C2333;
  --chalk: #F0F2F5;
  --blueprint: #2563EB;
  --teal: #0D9488;
  --amber: #D97706;
  --line: #334155;
  --white: #FFFFFF;
  --plinth: #94A3B8;

  --font-heading: 'DM Sans', system-ui, sans-serif;
  --font-body: 'IBM Plex Sans', system-ui, sans-serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;

  --container-max: 1280px;
  --gutter: 24px;
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--slate);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img, svg { display: block; max-width: 100%; }
button { font: inherit; cursor: pointer; }
a { color: inherit; }
h1, h2, h3, h4 { margin: 0; font-family: var(--font-heading); font-weight: 700; letter-spacing: -0.02em; line-height: 1.15; }
p { margin: 0; }
ul, ol { margin: 0; padding: 0; list-style: none; }

/* Container */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 32px;
}

/* Mono utility */
.mono {
  font-family: var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 11px;
  font-weight: 500;
}

/* ==========================================================================
   Header / Navigation
   ========================================================================== */
.site-header {
  background: var(--slate);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 50;
}
.site-header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 32px;
  max-width: var(--container-max);
  margin: 0 auto;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--white);
}
.brand__mark {
  width: 32px;
  height: 32px;
  display: block;
}
.brand__name {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 17px;
  letter-spacing: -0.01em;
}
.brand__tag {
  display: block;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--plinth);
  margin-top: 2px;
}

.site-nav {
  display: flex;
  gap: 28px;
  align-items: center;
}
.site-nav a {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--plinth);
  text-decoration: none;
  transition: color 0.15s ease;
  padding: 6px 0;
  position: relative;
}
.site-nav a:hover { color: var(--white); }
.site-nav a.active {
  color: var(--white);
}
.site-nav a.active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -8px;
  height: 2px;
  background: var(--blueprint);
}
.nav-toggle { display: none; }

@media (max-width: 768px) {
  .site-header__inner { padding: 14px 20px; }
  .site-nav { display: none; flex-direction: column; gap: 16px; align-items: flex-start; }
  .site-nav.open {
    display: flex;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--slate);
    padding: 20px;
    border-bottom: 1px solid var(--line);
  }
  .nav-toggle {
    display: inline-flex;
    background: transparent;
    border: 1px solid var(--line);
    color: var(--white);
    padding: 8px 14px;
    font-family: var(--font-mono);
    font-size: 11px;
    letter-spacing: 0.16em;
    text-transform: uppercase;
  }
  .brand__tag { display: none; }
}

/* ==========================================================================
   Footer
   ========================================================================== */
.site-footer {
  background: var(--slate);
  color: var(--plinth);
  border-top: 1px solid var(--line);
  padding: 60px 0 32px;
}
.site-footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
}
.site-footer h4 {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--amber);
  margin-bottom: 16px;
}
.site-footer .brand {
  margin-bottom: 16px;
}
.site-footer__about {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.6;
  color: var(--plinth);
  max-width: 38ch;
}
.site-footer ul li { margin-bottom: 8px; }
.site-footer ul a {
  font-family: var(--font-body);
  font-size: 14px;
  text-decoration: none;
  color: var(--plinth);
  transition: color 0.15s ease;
}
.site-footer ul a:hover { color: var(--white); }
.site-footer__bottom {
  border-top: 1px solid var(--line);
  margin-top: 48px;
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}
.site-footer__bottom span {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--plinth);
}

@media (max-width: 900px) {
  .site-footer__grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 600px) {
  .site-footer__grid { grid-template-columns: 1fr; gap: 32px; }
}

/* ==========================================================================
   Buttons
   ========================================================================== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 28px;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.02em;
  text-decoration: none;
  border: none;
  border-radius: 0;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
  white-space: nowrap;
}
.btn-primary {
  background: var(--blueprint);
  color: var(--white);
}
.btn-primary:hover { background: #1d54d9; }
.btn-outline-light {
  background: transparent;
  color: var(--white);
  border: 1px solid var(--white);
}
.btn-outline-light:hover { background: var(--white); color: var(--slate); }
.btn-outline-blue {
  background: transparent;
  color: var(--blueprint);
  border: 1px solid var(--blueprint);
  padding: 10px 20px;
  font-size: 13px;
}
.btn-outline-blue:hover { background: var(--blueprint); color: var(--white); }
.btn-teal {
  background: var(--teal);
  color: var(--white);
  padding: 14px 32px;
}
.btn-teal:hover { background: #0a7468; }
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 15px;
  color: var(--white);
  text-decoration: none;
}
.text-link .arrow {
  color: var(--amber);
  font-size: 16px;
  transition: transform 0.15s ease;
}
.text-link:hover { color: var(--blueprint); }
.text-link:hover .arrow { transform: translateX(4px); }

/* ==========================================================================
   Eyebrow with rule
   ========================================================================== */
.eyebrow {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--amber);
  display: inline-flex;
  align-items: center;
  gap: 12px;
}
.eyebrow::before {
  content: "";
  display: inline-block;
  width: 24px;
  height: 1.5px;
  background: var(--amber);
}
.eyebrow.no-rule::before { display: none; }
.eyebrow.teal { color: var(--teal); }
.eyebrow.teal::before { background: var(--teal); }
.eyebrow.plinth { color: var(--plinth); }
.eyebrow.plinth::before { background: var(--plinth); }

/* ==========================================================================
   Section base
   ========================================================================== */
section {
  position: relative;
}

/* ==========================================================================
   HERO (home-section-1)
   ========================================================================== */
.hero {
  background: var(--slate);
  color: var(--white);
  padding: 120px 0 96px;
  min-height: 92vh;
  display: flex;
  align-items: center;
  position: relative;
}
.hero__inner {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 32px;
}
.hero__eyebrow {
  margin-bottom: 40px;
}
.hero__headline {
  font-family: var(--font-heading);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.05;
  font-size: clamp(42px, 8.5vw, 112px);
  color: var(--white);
  margin: 0;
  max-width: 14ch;
}
.hero__headline .accent {
  color: var(--blueprint);
  display: block;
}
.hero__rule {
  height: 1px;
  width: 100%;
  background: var(--line);
  margin: 36px 0;
  max-width: 1100px;
}
.hero__sub {
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.6;
  color: var(--plinth);
  max-width: 52ch;
  margin: 0 0 32px;
}
.hero__ctas {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.hero__bottom-rule {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--line);
}
@media (max-width: 768px) {
  .hero { padding: 80px 0 60px; min-height: auto; }
  .hero__ctas { flex-direction: column; align-items: stretch; gap: 12px; }
}

/* ==========================================================================
   STATS strip (home-section-2)
   ========================================================================== */
.stats-strip {
  background: var(--blueprint);
  color: var(--white);
  padding: 56px 0 64px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
