@media (max-width: 900px) {
  .story__inner { grid-template-columns: 1fr; gap: 32px; }
  .story__left { padding-right: 0; border-right: 0; order: 2; }
  .story__right { padding-left: 0; align-items: flex-start; order: 1; }
  .story__year-label { text-align: left; }
}

/* ==========================================================================
   Contact block (inquiries-section-2)
   ========================================================================== */
.contact {
  background: var(--chalk);
  padding: 100px 0;
}
.contact__inner {
  display: grid;
  grid-template-columns: 4fr 8fr;
  gap: 0;
  align-items: stretch;
}
.contact__sidebar {
  padding-right: 40px;
  border-right: 1px solid var(--line);
}
.contact__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 28px;
  letter-spacing: -0.02em;
  color: var(--line);
  margin-top: 16px;
}
.contact__sub {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--line);
  margin-top: 20px;
}
.contact__body {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.65;
  color: var(--plinth);
  margin-top: 24px;
}
.contact__badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--teal);
  border: 1px solid var(--line);
  padding: 8px 12px;
  margin-top: 32px;
}
.contact__form {
  background: var(--white);
  border: 2px solid var(--line);
  padding: 40px;
  margin-left: 40px;
}
.form-field {
  padding: 16px 0 24px;
  border-bottom: 1px solid var(--line);
}
.form-field:first-child { padding-top: 0; }
.form-field:last-of-type { border-bottom: 0; padding-bottom: 0; }
.form-field__label {
  display: block;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--line);
  margin-bottom: 4px;
}
.form-field__desc {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--plinth);
  margin-bottom: 8px;
}
.form-field__input,
.form-field__textarea {
  width: 100%;
  border: 1px solid var(--line);
  background: var(--chalk);
  padding: 12px;
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--line);
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s ease, border-width 0.15s ease;
}
.form-field__input:focus,
.form-field__textarea:focus {
  border: 2px solid var(--blueprint);
  padding: 11px;
}
.form-field__textarea { resize: vertical; min-height: 120px; font-family: var(--font-body); }
.contact__submit {
  margin-top: 32px;
}
@media (max-width: 900px) {
  .contact__inner { grid-template-columns: 1fr; gap: 32px; }
  .contact__sidebar { padding-right: 0; border-right: 0; padding-bottom: 32px; border-bottom: 1px solid var(--line); }
  .contact__form { margin-left: 0; padding: 28px; }
}

/* ==========================================================================
   Process steps (inquiries-section-3)
   ========================================================================== */
.process {
  background: var(--slate);
  color: var(--white);
  padding: 80px 0 72px;
}
.process__head { margin-bottom: 0; }
.process__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(26px, 3vw, 36px);
  letter-spacing: -0.02em;
  color: var(--white);
  margin-top: 12px;
  max-width: 24ch;
}
.process__rule-top {
  height: 1px;
  background: var(--line);
  margin: 48px 0 0;
}
.process__rule-bottom {
  height: 1px;
  background: var(--line);
  margin: 0 0 32px;
}
.process__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}
.process-step {
  padding: 32px 32px 32px 0;
  border-left: 1px solid var(--line);
  padding-left: 32px;
}
.process-step:first-child { border-left: 0; padding-left: 0; }
.process-step__number {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 48px;
  line-height: 1;
  color: var(--blueprint);
}
.process-step__title {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 18px;
  color: var(--white);
  margin-top: 16px;
  line-height: 1.2;
}
.process-step__desc {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.6;
  color: var(--plinth);
  margin-top: 12px;
}
.process__cta {
  margin-top: 32px;
}
@media (max-width: 900px) {
  .process__grid { grid-template-columns: 1fr; }
  .process-step { border-left: 0; border-top: 1px solid var(--line); padding-left: 0; padding-top: 24px; padding-bottom: 24px; }
  .process-step:first-child { border-top: 0; padding-top: 0; }
}

/* ==========================================================================
   Helpers
   ========================================================================== */
.flush-rule {
  height: 1px;
  background: var(--line);
  width: 100%;
}
.section-tag {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

input.content:
// Visual-only behaviors

(function () {
  // Mobile nav toggle
  var toggle = document.querySelector('.nav-toggle');
  var nav = document.querySelector('.site-nav');
  if (toggle && nav) {
    toggle.addEventListener('click', function () {
      nav.classList.toggle('open');
    });
  }

  // FAQ accordion
  var faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(function (item) {
    var btn = item.querySelector('.faq-item__btn');
    if (!btn) return;
    btn.addEventListener('click', function () {
      var isOpen = item.classList.toggle('open');
      var toggleEl = item.querySelector('.faq-item__toggle');
      if (toggleEl) toggleEl.textContent = isOpen ? '−' : '+';
    });
  });

  // Inquiry form — visual feedback only
  var form = document.querySelector('.contact__form');
  if (form) {
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      var btn = form.querySelector('.contact__submit');
      if (btn) {
        var original = btn.textContent;
        btn.textContent = 'Submitted ✓';
        btn.disabled = true;
        setTimeout(function () {
          btn.textContent = original;
          btn.disabled = false;
        }, 2400);
      }
    });
  }
})();

